import Foundation
import AVFoundation
import CoreVideo
import ImageIO
import SwiftSignalKit
import XCTest

final class TimingTests:XCTestCase {
 func testKeyFrameIsRelativeToTrimStart() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:10,leftTrim:0.2,rightTrim:0.8,keyFrame:0.5));XCTAssertEqual(value.timeRange.start.seconds,2);XCTAssertEqual(value.timeRange.duration.seconds,6);XCTAssertEqual(value.thumbnailTime.seconds,5);XCTAssertEqual(value.keyFrame,3)}
 func testKeyFrameBeforeTrimClampsToFirstFrame() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:10,leftTrim:0.2,rightTrim:0.8,keyFrame:0.1));XCTAssertEqual(value.thumbnailTime.seconds,2);XCTAssertEqual(value.keyFrame,0)}
 func testKeyFrameAfterTrimClampsInsideLastFrame() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:10,leftTrim:0.2,rightTrim:0.8,keyFrame:0.9));XCTAssertEqual(value.thumbnailTime.seconds,7.95);XCTAssertEqual(try XCTUnwrap(value.keyFrame),5.95,accuracy:0.001)}
 func testKeyFrameAtEndDoesNotRequestFrameBeyondClip() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:1,leftTrim:0,rightTrim:1,keyFrame:1));XCTAssertEqual(value.thumbnailTime.seconds,0.95);XCTAssertEqual(value.keyFrame,0.95)}
 func testNoKeyFrameUsesTrimStartAndPreservesNil() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:10,leftTrim:0.2,rightTrim:0.8,keyFrame:nil));XCTAssertEqual(value.thumbnailTime.seconds,2);XCTAssertNil(value.keyFrame)}
 func testShortClipUsesFirstFrameRatherThanNegativeTime() throws {let value=try XCTUnwrap(EditedAvatarVideoRange(duration:1,leftTrim:0.2,rightTrim:0.22,keyFrame:0.21));XCTAssertEqual(value.thumbnailTime.seconds,0.2);XCTAssertEqual(value.keyFrame,0)}
 func testInvalidDurationsAndNonFiniteValuesAreRejected() {for duration in [0,-1,Double.nan,Double.infinity,Double.greatestFiniteMagnitude] {XCTAssertNil(EditedAvatarVideoRange(duration:duration,leftTrim:0,rightTrim:1,keyFrame:nil))};for value in [Double.nan,Double.infinity,-Double.infinity] {XCTAssertNil(EditedAvatarVideoRange(duration:10,leftTrim:value,rightTrim:1,keyFrame:nil));XCTAssertNil(EditedAvatarVideoRange(duration:10,leftTrim:0,rightTrim:value,keyFrame:nil));XCTAssertNil(EditedAvatarVideoRange(duration:10,leftTrim:0,rightTrim:1,keyFrame:value))}}
 func testInvalidOrSubMillisecondTrimIsRejected() {for (left,right) in [(-0.1,1.0),(0.0,1.1),(0.5,0.5),(0.7,0.2),(0.0,0.0001)] {XCTAssertNil(EditedAvatarVideoRange(duration:1,leftTrim:left,rightTrim:right,keyFrame:nil))}}
}
final class NativeTests:XCTestCase {
 var paths:[String]=[]
 override func tearDown() {for path in paths {try? FileManager.default.removeItem(atPath:path)}}
 func source() throws -> (AVMutableComposition,AVMutableVideoComposition) {
  let writer=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);var pixel:CVPixelBuffer?;XCTAssertEqual(CVPixelBufferCreate(kCFAllocatorDefault,640,640,kCVPixelFormatType_32ARGB,nil,&pixel),kCVReturnSuccess);let buffer=try XCTUnwrap(pixel);CVPixelBufferLockBaseAddress(buffer,[]);if let address=CVPixelBufferGetBaseAddress(buffer) {memset(address,255,CVPixelBufferGetDataSize(buffer))};CVPixelBufferUnlockBaseAddress(buffer,[])
  let queue=DispatchQueue(label:"edited-avatar-source");let done=expectation(description:"source");var path:String?;var frame=0
  queue.async {writer.start(queue:queue,isCancelled:{false},next:{if frame==30 {return .finished(CMTime(seconds:1,preferredTimescale:30))};defer {frame+=1};return .frame(buffer,CMTime(value:Int64(frame),timescale:30))},completed:{path=$0;done.fulfill()})};wait(for:[done],timeout:20)
  let output=try XCTUnwrap(path);paths.append(output);let asset=AVURLAsset(url:URL(fileURLWithPath:output));let track=try XCTUnwrap(asset.tracks(withMediaType:.video).first);let result=AVMutableComposition();let copied=try XCTUnwrap(result.addMutableTrack(withMediaType:.video,preferredTrackID:kCMPersistentTrackID_Invalid));try copied.insertTimeRange(CMTimeRange(start:.zero,duration:asset.duration),of:track,at:.zero)
  let video=AVMutableVideoComposition();video.renderSize=CGSize(width:640,height:640);video.frameDuration=CMTime(value:1,timescale:30);let layer=AVMutableVideoCompositionLayerInstruction(assetTrack:copied);let instruction=AVMutableVideoCompositionInstruction();instruction.timeRange=CMTimeRange(start:.zero,duration:result.duration);instruction.layerInstructions=[layer];video.instructions=[instruction];return(result,video)
 }
 func testRealTrimmedVideoAndThumbnailAreReadable() throws {let (asset,composition)=try source();let done=expectation(description:"export");var events:[VideoAvatarGeneratorState]=[];let d=generateEditedAvatarVideo(asset,composition:composition,quality:AVAssetExportPresetHighestQuality,leftTrim:0.2,rightTrim:0.8,keyFrame:0.5).start(next:{events.append($0)},completed:{done.fulfill()});wait(for:[done],timeout:30);d.dispose();let result=try XCTUnwrap(events.compactMap {value -> (String,String,Double?)? in if case let .complete(thumb,video,key)=value {return(thumb,video,key)};return nil}.first);paths += [result.0,result.1];let video=AVURLAsset(url:URL(fileURLWithPath:result.1));XCTAssertEqual(video.duration.seconds,0.6,accuracy:0.05);XCTAssertEqual(video.tracks(withMediaType:.video).count,1);XCTAssertEqual(try XCTUnwrap(result.2),0.3,accuracy:0.001);let source=try XCTUnwrap(CGImageSourceCreateWithURL(URL(fileURLWithPath:result.0) as CFURL,nil));let image=try XCTUnwrap(CGImageSourceCreateImageAtIndex(source,0,nil));XCTAssertEqual(image.width,640);XCTAssertEqual(image.height,640);XCTAssertFalse(events.contains(.error))}
 func testUnsupportedNativePresetTerminates() throws {let (asset,composition)=try source();let done=expectation(description:"failure");var events:[VideoAvatarGeneratorState]=[];let d=generateEditedAvatarVideo(asset,composition:composition,quality:"invalid-avatar-preset",leftTrim:0,rightTrim:1,keyFrame:nil).start(next:{events.append($0)},completed:{done.fulfill()});wait(for:[done],timeout:10);d.dispose();XCTAssertEqual(events,[.error])}
 func testEmptyNativeCompositionTerminates() {let done=expectation(description:"failure");var events:[VideoAvatarGeneratorState]=[];let d=generateEditedAvatarVideo(AVMutableComposition(),composition:AVMutableVideoComposition(),quality:AVAssetExportPresetHighestQuality,leftTrim:0,rightTrim:1,keyFrame:nil).start(next:{events.append($0)},completed:{done.fulfill()});wait(for:[done],timeout:10);d.dispose();XCTAssertEqual(events,[.error])}
 func testNativeCancellationAfterThumbnailRemovesIt() throws {let (asset,composition)=try source();let started=expectation(description:"thumbnail");let d=MetaDisposable();var thumbnail:String?;EditedAvatarVideoExport.queue.sync {d.set(generateEditedAvatarVideo(asset,composition:composition,quality:AVAssetExportPresetHighestQuality,leftTrim:0,rightTrim:1,keyFrame:nil).start(next:{value in if case let .start(path)=value {thumbnail=path;d.dispose();started.fulfill()};if case .complete=value {XCTFail("Cancelled export published files")}}))};wait(for:[started],timeout:10);EditedAvatarVideoExport.queue.sync {};let path=try XCTUnwrap(thumbnail);XCTAssertFalse(FileManager.default.fileExists(atPath:path))}

}
